parameters.jsCode:
const payload = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const lead = payload.lead || {};
const seller = payload.seller || payload.vendedor || {};
const metadata = payload.metadata || {};

const requiredString = (value) => String(value ?? '').trim();
const nullableString = (value) => {
  const text = requiredString(value);
  return text || null;
};
const normalizePhone = (value) => {
  const digits = String(value ?? '').replace(/\D/g, '');

  if (!digits) {
    return '';
  }

  if ((digits.length === 10 || digits.length === 11) && !digits.startsWith('55')) {
    return `55${digits}`;
  }

  return digits;
};

const nome = requiredString(lead.name ?? payload.nome ?? payload.name);
const telefone = normalizePhone(lead.phone ?? payload.whatsapp ?? payload.phone ?? payload.telefone);
const email = nullableString(lead.email ?? payload.email)?.toLowerCase() || null;
const servico = nullableString(lead.serviceInterest ?? payload.serviceInterest ?? payload.interesse ?? payload.servico) || 'outro';
const mensagem = nullableString(lead.message ?? payload.message ?? payload.mensagem);
const companyName = nullableString(lead.companyName ?? payload.empresa ?? payload.companyName);
const vendedor = {
  nome: nullableString(seller.name ?? seller.nome),
  telefone: normalizePhone(seller.phone ?? seller.telefone) || null
};
const origem = {
  company: requiredString(payload.company) || 'BACKE.co',
  environment: requiredString(payload.environment) || 'sandbox',
  source: requiredString(payload.source) || 'website',
  formId: nullableString(payload.formId),
  pageUrl: nullableString(payload.pageUrl),
  pageTitle: nullableString(payload.pageTitle),
  utm: payload.utm && typeof payload.utm === 'object' ? payload.utm : {}
};
const consentimento = payload.consentimento && typeof payload.consentimento === 'object'
  ? payload.consentimento
  : {
      marketing: true,
      source: 'website-contact-form',
      capturedAt: metadata.submittedAt || new Date().toISOString()
    };
const normalizedMetadata = {
  ...metadata,
  companyName,
  vendedor,
  idempotencyKey: metadata.idempotencyKey || payload.idempotencyKey || null,
  normalizedAt: new Date().toISOString()
};
const errors = [];

if (!nome) {
  errors.push('Informe seu nome.');
}

if (!telefone) {
  errors.push('Informe seu WhatsApp.');
}

if (telefone && (telefone.length < 10 || telefone.length > 15)) {
  errors.push('Informe um WhatsApp válido.');
}

if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  errors.push('Informe um email válido.');
}

return [
  {
    json: {
      valid: errors.length === 0,
      errors,
      nome,
      telefone,
      email,
      servico,
      mensagem,
      origem,
      consentimento,
      metadata: normalizedMetadata,
      raw_payload: payload,
      vendedor
    }
  }
];

const lead = $('Postgres - Salvar Lead').first().json;

return [
  {
    json: {
      ok: true,
      dryRun: true,
      lead_id: lead.lead_id,
      whatsapp_cliente_enviado: true,
      whatsapp_vendedor_enviado: true,
      cliente: {
        number: lead.telefone,
        text: `Olá, ${lead.nome}! Recebemos seu contato na BACKE.co. Um especialista vai falar com você em breve para seguir com seu diagnóstico.`
      },
      vendedor: {
        number: lead.metadata?.vendedor?.telefone || $env.DEFAULT_SELLER_PHONE || 'SIMULATED_SELLER_PHONE',
        text: `Novo lead BACKE.co\nID: ${lead.lead_id}\nNome: ${lead.nome}\nWhatsApp: ${lead.telefone}\nEmail: ${lead.email || 'não informado'}\nEmpresa: ${lead.metadata?.companyName || 'não informado'}\nInteresse: ${lead.servico || 'não informado'}\nOrigem: ${lead.origem?.source || 'website'} - ${lead.origem?.pageUrl || 'sem URL'}`
      }
    }
  }
];

